```{.python .cell-code}
data = data_import.with_columns(
    points_differential=pl.col("home_score") - pl.col("away_score")
).with_columns(
    home_win=pl.when(pl.col("points_differential") > 0).then(1).otherwise(0),
    away_win=pl.when(pl.col("points_differential") < 0).then(1).otherwise(0),
    draw=pl.when(pl.col("points_differential") == 0).then(1).otherwise(0),
)

# Calculate final competition ladder for each season -------------------


def competition_table(df):
    home_stats = (
        df.group_by("season", "home")
        .agg(
            pl.col("home_win").sum().alias("home_wins"),
            pl.col("points_differential").sum().alias("home_for_and_against"),
        )
        .rename({"home": "team"})
    )

    away_stats = (
        df.group_by("season", "away")
        .agg(
            pl.col("away_win").sum().alias("away_wins"),
            (pl.col("points_differential").sum() * -1).alias("away_for_and_against"),
        )
        .rename({"away": "team"})
    )

    draw_stats = (
        df.group_by("season", "home")
        .agg(pl.col("draw").sum().alias("draw"))
        .rename({"home": "team"})
    )

    return (
        home_stats.join(away_stats, on=["season", "team"], how="left")
        .join(draw_stats, on=["season", "team"], how="left")
        .with_columns(
            (pl.col("home_wins") + pl.col("away_wins") + pl.col("draw") * 0.5).alias(
                "total_wins"
            ),
            (pl.col("home_for_and_against") + pl.col("away_for_and_against")).alias(
                "for_and_against"
            ),
        )
        .select("season", "team", "total_wins", "for_and_against")
        .sort(
            ["season", "total_wins", "for_and_against"],
            descending=[False, True, True],
            maintain_order=True,
        )
        .with_columns(
            pl.int_range(1, pl.len() + 1)
            .over("season")
            .alias("regular_season_position")
        )
        .with_columns(
            pl.when(pl.col("regular_season_position") <= 8)
            .then(1)
            .otherwise(0)
            .alias("made_finals")
        )
    )


observed_summary_results = competition_table(data)

observed_results_tbl = GT(observed_summary_results.head(16))

observed_results_tbl
