# Calculate proportions ----------------------------
probabilities_simulated = (
    simulation_summary_results.group_by("total_wins")
    .agg(
        count_made_finals=pl.col("made_finals").sum(),
        total_count=pl.len(),
    )
    .with_columns(percentage=pl.col("count_made_finals") / pl.col("total_count"))
    .sort("total_wins", descending=True)
)

# Create table --------------------------------------
finals_probability_tbl = (
    GT(
        probabilities_simulated.with_columns(
            total_wins=pl.format("{} wins", pl.col("total_wins").cast(pl.Int64))
        ),
        rowname_col="total_wins",
    )
    .fmt_integer(columns=["total_count", "count_made_finals"])
    .fmt_percent(columns="percentage", decimals=1)
    .tab_header(
        title="NRL teams need to win 13 games to be confident of playing finals",
        subtitle="Finals probabilities based on results from 10,000 simulated seasons",
    )
    .cols_label(
        total_count="Simulated occurrences",
        count_made_finals="Times qualified",
        percentage="Finals probability",
    )
)

